import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import 'package:zan/Core/Resources/app_colors.dart';import 'package:zan/Core/Utils/Extensions/localizations_extension.dart';import '../../../../../../Config/app_config.dart';import '../../../../../../Core/Resources/app_icons.dart';import '../../../../../../Core/Utils/Widget/loading_animation.dart';import '../../../../../../Core/Utils/Extensions/widget_extension.dart';import '../../../../../../Config/Routes/route_name.dart';import '../../../../../../Core/Resources/app_fonts.dart';import '../../../../../../Core/Utils/Widget/Images/build_image.dart';import '../../../../../../main.dart';import '../../domain/UseCase/add_to_Cart_use_case.dart';import '../../domain/UseCase/get_details_product_use_case.dart';import '../../domain/repository/product_details_repo_impl.dart';import '../Manager/product_details_cubit.dart';import '../components/build_button_add_cart.dart';import '../components/tab_bar_products.dart';class ProductDetailsScreen extends StatelessWidget {  final int id;  const ProductDetailsScreen({super.key, required this.id});  @override  Widget build(BuildContext context) {    return BlocProvider(      create: (context) =>      ProductDetailsCubit(        GetDetailsProductUseCase(          productDetailsRepoImpl: ProductDetailsRepoImpl(),        ),        AddToCartUseCase(          productDetailsRepoImpl: ProductDetailsRepoImpl(),        ),      )        ..getProductDetails(id: id),      child: BlocBuilder<ProductDetailsCubit, ProductDetailsState>(        builder: (context, state) {          return Scaffold(            appBar: AppBar(              actions: [                12.horizontalSpace,                InkWell(                  onTap: () => kNavigationService.navigateTo(AppRoutes.cart),                  child: AppIcons.bag,                ),                AppConfig.customPaddingFromRightLeft.horizontalSpace,              ],            ),            body: state.isLoading == true                ? CustomLoadingAnimation()                : [              SliverToBoxAdapter(                child: Column(                  children: [                    SizedBox(                      height: 300.h,                      child: PageView.builder(                        onPageChanged: (index) =>                            context                                .read<ProductDetailsCubit>()                                .changeIndex(index),                        itemCount: state.product!.images.length,                        itemBuilder: (context, index) =>                            BuildImageAssets(                              height: 300.h,                              width: 1.sw,                              url: state.product!.images[index].imageUrl,                            ),                      ),                    ),                    10.verticalSpace,                    Row(                      mainAxisAlignment: MainAxisAlignment.center,                      children: List.generate(                        state.product!.images.length,                            (index) =>                            AnimatedContainer(                              duration: Duration(milliseconds: 300),                              margin: EdgeInsets.symmetric(horizontal: 4),                              height: 8.h,                              width: 8.w,                              decoration: BoxDecoration(                                shape: BoxShape.circle,                                color: state.index == index                                    ? AppColors.primaryColor                                    : AppColors.grayscale60,                              ),                            ),                      ),                    ),                  ],                ),              ),              SliverToBoxAdapter(                child: Padding(                  padding: const EdgeInsets.all(8.0),                  child: state.product?.model3D == null                      ? SizedBox()                      : Row(                    children: [                      InkWell(                          onTap: () {                            kNavigationService.navigateTo(                                AppRoutes.screen3D,                                arguments: state.product?.model3D);                          },                          child: Text(                            "3D",                            style: AppTextStyles.h6Bold,                          )),                      20.horizontalSpace,                      InkWell(                          onTap: () {                            kNavigationService                                .navigateTo(AppRoutes.aRViewScreen);                          },                          child: Text(                            "3D(AR)",                            style: AppTextStyles.h6Bold,                          )),                    ],                  ),                ),              ),              TabBarProducts()            ].styledAppPages(withScroll: true, withPadding: true),            persistentFooterButtons: [              BuildButtonBottomScreen(                nameButton:context.local.AddToCart,                onPressed: () {},                price: state.product?.price??"00",                disCountPrice:state.product?.discountPrice,              ),            ],          );        },      ),    );  }}